/// Remove duplicates from `nums`, keeping only the first occurrence of each
/// element, in the same relative order.
/// 
/// Specification:
///  1) No element appears more than once in the result.
///  2) Every element that appears in the result appears at least once in `nums`.
///  3) Every distinct element of `nums` appears exactly once in the result.
///  4) The order of first occurrences is preserved.
#[requires(true)]
#[ensures(forall(|x: i32| count(&result, x) <= 1))]
#[ensures(forall(|x: i32| count(&result, x) == 1 <==> count(&nums, x) >= 1))]
#[ensures(preserves_order(&nums, &result))]
pub fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = std::collections::HashSet::new();
    let mut result = Vec::with_capacity(nums.len());
    for x in nums {
        // Insert returns true if the value was not present in the set yet
        if seen.insert(x) {
            result.push(x);
        }
    }
    result
}

